insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (169, 'Bách Thảo Tinh', 19, 95, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: Vua thực vật sinh sống tại Linh Lan, cực mạnh và đầy quyền lực, gần đây hắn đang triệu tập lực lượng để chống lại các gia tộc.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (170, 'Phủ Ma', 21, 95, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: Yêu thú hấp thụ sự hắc ám, vẻ ngoài cực kỳ hung ác khiến cho không ai dám đến gần, khi hắn vung chiếc rìu khổng lồ trên tay là lúc Vô Ưu Đại Lục đối diện với đạn nạn.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (171, 'Ma Chiến', 23, 110, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: Ma chiến sĩ có thể điều khiển được hiện thực và giấc mơ, tính cách kỳ dị, pháp thuật vô biên.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (182, 'Chiến Thần', 42, 60, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: 1 trong số ngũ đại yêu ma đối đầu với phe chính nghĩa, khi xuất hiện thì toàn thân tỏa ra ngọn lửa yêu ma quái dị, chân tướng thật sự đến nay vẫn chưa ai biết.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (183, 'Ma Thần', 35, 70, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: 1 trong số ngũ đại yêu ma đối đầu với phe chính nghĩa, khi xuất hiện thì toàn thân tỏa ra ngọn lửa yêu ma quái dị, chân tướng thật sự đến nay vẫn chưa ai biết.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (184, 'Tà Thần', 22, 80, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: 1 trong số ngũ đại yêu ma đối đầu với phe chính nghĩa, khi xuất hiện thì toàn thân tỏa ra ngọn lửa yêu ma quái dị, chân tướng thật sự đến nay vẫn chưa ai biết.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (185, 'Tử Thần', 23, 90, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: 1 trong số ngũ đại yêu ma đối đầu với phe chính nghĩa, khi xuất hiện thì toàn thân tỏa ra ngọn lửa yêu ma quái dị, chân tướng thật sự đến nay vẫn chưa ai biết.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (706, 'Thất Sắc Kê', 3, 5, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Lông đuôi của loại Thất Kê Sắc này có 7 màu sặc sỡ, là loại quái có mức độ nguy hiểm giống như Kê Vương ở Vân Đài.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (707, 'Thỏ Điên Răng Vổ', 2, 10, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Thỏ Răng Vố vốn là một sinh vật nhỏ bé đáng yêu ở Vô Ưu Đại Lục, nhưng từ khi bị tác động của một sức mạnh thần bí nào đó, chúng ngày càng trở nên điên cuồng, chúng thường tấn công người qua đường một cách hung tợn, dần dần, mọi người gọi chúng là Thỏ Điên');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (708, 'Trưởng Lão Sơn Quái', 4, 15, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Thật ra loại tiểu quái độc nhãn này không phải là quái vật, chúng vốn là các Tinh Linh Nham Thạch tu hành trong núi, sống thành quần thể trong rừng sâu, mỗi quần thể do một vị trưởng lão dẫn đầu. Loại tinh linh này không thích tấn công, nhưng lại có ý thức mạnh mẽ về lãnh địa, chúng sẽ dồn hết sức tấn công con người nếu họ xâm chiếm lãnh địa của chúng.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (709, 'Ma Vương Bát Giác', 15, 20, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Người thống trị toàn bộ Lê Dương Hồ chính là bộ tộc Bạch Tuộc, tộc trưởng của họ là một con Bạch Tuộc khổng lồ tự xưng là Ma Vương Bát Giác, tên này có dã tâm vô cùng to lớn, hắn không chỉ xưng bá ở Lê Dương Hồ mà còn tuyên bố muốn thống trị thế giới dưới nước ở trên toàn Đại Lục.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (710, 'Quân Sư Cẩu Đầu', 40, 20, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Nhóm Đạo Tặc Sa Mạc tàn sát bừa bãi ở phía Tây của Vô Ưu Đại Lục, là cơn ác mộng của mọi thương nhân, hai tên Quân Sư Cẩu Đầu của chúng là những kẻ rất biết bày mưu tính kế, chúng đã thống lĩnh nhóm đạo tặc chiếm cứ Thiên Lục Châu duy nhất trên sa mạc.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (711, 'Ốc Giáo Quan', 17, 30, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Tập đoàn Ốc là kẻ bám đuôi bộ tộc Bạch Tuộc tren Lê Dương Hồ, Ốc Giáo Quan lợi dụng ưu thế của lớp vỏ cứng cáp vốn có của ốc để huấn luyện ra nhiều nhóm Cận Vệ giỏi cho Đại Vương Bạch Tuộc.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (712, 'Cổ Thụ Lão Yêu', 26, 30, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Sống trong rừng cổ thụ ở Quang Bình Nguyên, có một số cổ thụ lâu đời đã hóa thành tinh, nhưng bản tính của những cổ thụ này vốn rất ôn hòa, chỉ khi nào gặp nguy hiểm mới tấn công.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (713, 'Gấu Tuyết Tàn Bạo', 33, 25, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Gấu Tuyết Tàn Bạo chính là vương giả trong Lạp Tuyết Địa, lớp da lông dày đã tạo nên khả năng phòng ngự tuyệt vời cho chúng, những cái vuốt sắc bén chính là vũ khí tấn công tạo ra sức sát thương cao nhất.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (714, 'Chiến Thần Sói', 41, 35, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Sói là một sinh vật hung tàn và khát máu, nhưng Sói cũng có nguyên tắc riêng của Sói, chúng tôn thờ sức mạnh, chúng sẽ phục tùng cho sức mạnh lớn hơn chúng, vì vậy phải có một con đứng đầu trong bộ tộc Sói, đây là con sói mạnh mẽ nhất, được gọi là Chiến Thần Sói.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (715, 'Gấu Đen', 27, 45, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Gấu Đen là một loại mạnh nhất trong họ Gấu, sức mạnh của nó cao hơn 5 lần so với Gấu Tuyết, nếu bạn không địch lại Gấu Tuyết mà muốn khiêu chiến với Gấu Đen thì chẳng khác nào tự tìm cái chết.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (716, 'Miêu Vương', 34, 35, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Miêu Vương là một Tinh Linh thoắt ẩn thoắt hiện mà thiên nhiên ban cho Anh Vũ Cảnh, nó rất hiền lành và không xảo trá, khi bạn gặp nguy hiểm, nó sẽ âm thầm giúp đỡ bạn, nhưng khi tính trẻ con trỗi dậy thì nó cũng sẽ lén trêu chọc bạn đấy.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (717, 'Nấm Yêu Huyết Hồng', 27, 40, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Đây là loại Nấm Yêu được tạo thành do hấp thụ khí tà ác, toàn thân có màu đỏ rực, độc của nó không có gì so sánh được, nó luôn sử dụng những màu sắc sặc sỡ, bắt mắt để cám dỗ người qua đường để họ trở thành miếng mồi ngon giúp nó tiến hóa.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (718, 'Dạ Xoa Vương', 8, 45, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Dạ Xoa là yêu quái bóng đêm, chúng thường đi loanh quanh khắp nơi trong đêm tối, mỗi khi ăn được thịt người thì chúng rất vui, Dạ Xoa Vương là kẻ duy nhất có hai cánh trong lũ Dạ Xoa, nó có thể bay lên trời cao.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (719, 'Hấp Huyết Hoa Yêu', 34, 40, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Loại hoa khổng lồ này vốn không phải là yêu quái, nhưng thức ăn của nó là máu, nó luôn ẩn nấp trong rừng cây để săn bắt những loài động vật nhỏ để sinh sống, do sợ hãi nên con người đã gọi chúng là Hấp Huyết Hoa Yêu.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (822, 'Thủy Tinh Bào', 5, 55, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Tuy Thủy Tinh Bào sống ở Lê Dương Hồ, nhưng nó không hề lệ thuộc vào Bạch Tuộc Vương, nó là một loại sinh vật sống đan xen giữa động vật và thực vật, sở hữu một sức mạnh không thể tưởng tượng nổi.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (823, 'Cự Nhân Ma', 14, 60, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Tộc Cự Nhân là Man tộc sinh sống trong sa mạc từ thời viễn cổ đến nay, Cự Nhân Ma là người đứng đầu tộc, chiến tranh và  thảo phạt chính là ý nghĩa cuộc sống của họ.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (824, 'Hải Tinh Phệ Hồn', 6, 65, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Hải Tinh Phệ Hồn là đại phù thủy của bộ tộc Bạch Tuộc trong Lê Dương Thôn, ma lực phù phép của nó có thể giúp cho các chiến sĩ của đại quân Bạch Tuộc không biết mệt mỏi, không sợ mất mạng để chiến đấu tới cùng.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (825, 'Ác Ma Thượng Cổ', 42, 70, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Vào thời viễn cổ, Thái Thản của tộc người khổng lồ gây ra tội nghiệt và bị đày đến địa ngục, hóa thân thành Ác Ma, nó sở hữu sức mạnh to lớn từ sự căm phẫn đủ để hủy diệt mọi thứ.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (826, 'Ong Cửu Li Kịch Độc', 16, 75, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Ong Cửu Li Kịch Độc được đặt tên dựa vào độc tính của nó, tương truyền rằng chỉ cần bị gai độc của nó làm bị thương thì phải sau thời gian đủ để đi hết 9 dặm đường, độc tính của nó mới phát tác và gây tử vong, trong thời gian đó, cơ thể sẽ phải chịu nhiều giày vò, đau đớn.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (827, 'Thần Cuồng Bạo', 35, 75, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Vị thần bị ác ma Abate nô dịch và điều khiển, Abate đã cải tạo hắn, giúp hắn có được sức mạnh to lớn, nhưng hắn phải mất đi tất cả lý trí và chỉ nghe lệnh của Abate mà thôi.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (828, 'Ác Hổ Ma Giới', 28, 80, 'ground', 'normal', 'all', 'BGiới thiệu BOSS: Đây là nhóm binh sĩ mạnh mẽ dưới trướng của Tử Thần, có hình dạng như hổ nhưng thật ra không phải hổ, hình dạng hổ của chúng được tạo thành bằng cách tập hợp những linh hồn ai oán ở sâu dưới địa ngục, nhưng chúng rất hiếm khí xuất hiện ở thế giới loài người.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (829, 'Băng Cung Chiến Thần', 22, 85, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Là chiến sĩ có sức chiến đấu mạnh mẽ nhất trong thế giới băng tuyết, toàn thân được bao bọc bởi một lớp băng cứng, tay cầm Búa khổng lồ, là totem tinh thần cho các sinh linh trong thế giới  băng tuyết.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (918, 'Quỷ Vương', 24, 120, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: Yêu ma trong truyền thuyết đã từng hoành hành khắp Vô Ưu Đại Lục mấy trăm năm trước, sau đó bị các dũng sĩ Vô Ưu phong ấn lại. Thời gian trôi qua, phong ấn ngày càng yếu đi, với sức mạnh của mình, hắn đã phá vỡ phong ấn và quay lại quấy phá đại lục.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (920, 'Ác Thần', 29, 120, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: 1 trong số ngũ đại yêu ma đối đầu với phe chính nghĩa, khi xuất hiện thì toàn thân tỏa ra ngọn lửa yêu ma quái dị, chân tướng thật sự đến nay vẫn chưa ai biết.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (923, 'Thạch Yêu', 18, 90, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: Quái vật cực mạnh hình thành nhờ hấp thu sức mạnh hắc ám của trời đất, có thân hình cứng như đá và cực kỳ hung hãn, tốt nhất đừng nên chọc giận hắn.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1132, 'Avatar', 36, 130, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: Sứ giả thần bí từ một thế giới thần bí vượt không gian đến đây, có sức mạnh kỳ lạ và có ý thù địch với cư dân Vô Ưu Đại Lục.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1151, 'Atula Vương', 20, 135, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: Hiếu chiến, khát máu, muốn nuốt chửng tất cả, Atula Vương đại diện cho bóng tối, cho sự độc ác.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1163, 'Solomon', 56, 140, 'ground', 'mythic', 'channel:1', 'Giới thiệu BOSS: Vua ma thần vĩ đại, không chỉ cực mạnh mà còn là kẻ đứng đầu ma giới, lãnh đạo 72 ma thần.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1545, 'Yêu Quái Ẩn Trúc', 7, 90, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Là loại Trúc Yêu ẩn thân ở Quân Cổ Đạo, tuy nó có vẻ ốm yếu nhưng lại có sức mạnh tinh thần vô cùng to lớn, nếu không có sự kiên định mạnh mẽ thì sẽ dễ dàng bị nó khống chế.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1546, 'Cự Ma Ảo Thạch', 18, 95, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Là loại quái vật khổng lồ sở hữu sức mạnh của trái đất, nó là biểu tượng của thế lực ma quái, trên thế gian hiếm có ai chịu được một đòn tấn công của nó.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1547, 'Ma Cát Chỉ Phong', 21, 95, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Là loại quái vật kỳ dị sở hữu sức mạnh cuồng phong, nó không có hình dáng cụ thể, lúc ẩn lúc hiện, vì vậy sức phá hủy vật lý của nó không mạnh lắm, có điều sức mạnh ma pháp của nó đủ để làm cho người khác phải khiếp sợ.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1548, 'Siêu Nhân Gấu Trúc', 19, 100, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Không ai biết loài gấu trúc đáng yêu này đã đi đến Vô Ưu Đại Lục vào lúc nào, tuy có dáng vẻ ngây thơ, nhưng nó lại được kế thừa võ thuật thần bí của một quốc gia phương Đông nào đó.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1549, 'Tư Tế Ma Cốc', 23, 105, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Là Đại Tư Tế duy nhất trên thế gian của Ma Vương Abate, trấn thủ ở sâu bên trong Ma Cốc, hắn luôn nghĩ đủ cách để giải phong ấn cho Abate, vì vậy hắn đã đến trần gian một lần nữa.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1550, 'U Hồn Mê Quang', 29, 110, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Được tạo ra từ năng lượng nguyên tố tích tụ trong Mê Quang Tự, nó có khả năng điều khiển 4 nguyên tố để tạo thành trận pháp bảo vệ bản thân.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1551, 'Bóng Đen Thủ Hộ', 24, 115, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Là linh hồn lưu lạc trong chiến trường cổ ở Thủ Hộ Địa, nó không có suy nghĩ và ý thức, chỉ mang đầy ý niệm thù hận và bảo vệ, sẽ tiêu diệt tất cả những ai có ý muốn tiếp cận với nó.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1552, 'Lôi Nộ Chiến Ma', 61, 115, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Lôi Nộ Chiến Ma vốn là con người, sau đó được các vị thần chọn làm người phán quyết, ban cho sức mạnh của sấm chớp, trở thành cỗ máy chuyên đi tiêu diệt những kẻ tà ác.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1553, 'Đoạt Mộng Ma Linh', 36, 120, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Là quái vật lạ lấy giấc mơ của con người làm thức ăn, chỉ cần đặt chân vào Thần Di Cảnh thì sẽ bị Ma Linh chiếm đoạt, nó chính là nguồn gốc của giấc mơ của con người.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1554, 'Phù Thủy Thánh Ước', 20, 125, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Vốn là sứ giả lập khế ước với Thần, sau đó do khát khao sức mạnh ma pháp nên đã đi vào thế giới hắc ám, trở thành phù thủy, sự tồn tại của nó tượng trưng cho sự dung hợp giữa hai thế lực sáng và tối.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1555, 'Ma Vương Cực Địa', 43, 130, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Kẻ thống trị Đoạn Cốc, dã tâm của hắn rất lớn, huấn luyện Ma Binh ở Đoạn Cốc, tăng cường thực lực, mưu đồ lật đổ Abate để trở thành Ma Đế mới, thống lĩnh tam giới.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1556, 'Yêu Quái Mị Hoặc', 56, 140, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Mị Hoặc Lâm vốn là quê hương của Ảo Thuật Sư, trong một lần xảy ra kiếp nạn, các Ảo Thuật Sư ở trong rừng đã bị vong mạng, các vong hồn cứ lưu lại không chịu tan đi, rồi biến thành yêu quái cứ mãi ẩn dật trong rừng sâu.');
insert into data.data_tbl_schedule_boss (nid, name, map_id, level, kind, tier, channel_scope, description) values (1606, 'Phệ Quang Dạ Ma', 67, 121, 'ground', 'normal', 'all', 'Giới thiệu BOSS: Là một loại ma xà xuất hiện ở Vĩnh Dạ Cảng, vô cùng hung ác, sống trong bóng tối, ma lực vô biên làm cho con người khiếp đảm trong bóng tối.');
